    .hero-art::after { width: 110px; height: 120px; left: 30px; bottom: 30px; }

    .hero-chip {
      position: absolute;
      bottom: 24px;
      right: 24px;
      background: rgba(13, 9, 30, 0.42);
      color: #fff;
      border: 1px solid rgba(255,255,255,.32);
      border-radius: 999px;
      padding: 8px 13px;
      font-size: .82rem;
      font-weight: 600;
